#!/usr/bin/env bash
# ============================================================
#  Nara Bot — INSTALL SATU FILE (self-extracting)
#  Client tinggal jalankan:  bash install_nara.sh
#  Semua (persona + skill + config) sudah tertanam di dalam.
# ============================================================
set -euo pipefail

C_R='\033[0m'; C_C='\033[96m'; C_G='\033[92m'; C_Y='\033[93m'; C_B='\033[1m'
info()  { echo -e "${C_C}[*]${C_R} $*"; }
ok()    { echo -e "${C_G}[✓]${C_R} $*"; }
warn()  { echo -e "${C_Y}[!]${C_R} $*"; }
err()   { echo -e "\033[91m[✗]${C_R} $*"; exit 1; }

PROFILE_NAME="${1:-nara}"
NARA_VOICE_ID="KoyAe8gXlBuiHpl2i9FH"
HERMES_HOME_DIR="${HERMES_HOME:-$HOME/.hermes}"
PROFILE_DIR="$HERMES_HOME_DIR/profiles/$PROFILE_NAME"

echo -e "${C_B}${C_C}============================================================${C_R}"
echo -e "${C_B}${C_C}  NARA BOT — INSTALLER (1 file)${C_R}"
echo -e "${C_B}${C_C}============================================================${C_R}"
echo ""

# ---------- Prasyarat ----------
info "Memeriksa sistem..."
[ "$(uname -s)" = "Linux" ] || err "Script ini untuk Linux (VPS Ubuntu/Debian)."
command -v curl    >/dev/null 2>&1 || err "curl tidak ada. Install: apt install curl"
command -v git     >/dev/null 2>&1 || err "git tidak ada. Install: apt install git"
command -v python3 >/dev/null 2>&1 || err "python3 tidak ada."
command -v base64  >/dev/null 2>&1 || err "base64 tidak ada."
ok "Sistem dasar OK."

# ---------- Install Hermes ----------
if ! command -v hermes >/dev/null 2>&1; then
  info "Menginstall Hermes (sekali saja)..."
  curl -fsSL https://hermes-agent.nousresearch.com/install.sh | bash
  export PATH="$HOME/.local/bin:$HOME/.hermes/bin:$PATH"
  command -v hermes >/dev/null 2>&1 || err "Hermes gagal terpasang."
else
  info "Hermes sudah terpasang."
fi
ok "Hermes siap."

# ---------- Buat profile ----------
if [ ! -d "$PROFILE_DIR" ]; then
  info "Membuat profile '$PROFILE_NAME'..."
  hermes profile create "$PROFILE_NAME" >/dev/null 2>&1 || true
fi
mkdir -p "$PROFILE_DIR"
ok "Profile '$PROFILE_NAME' siap."

# ---------- Ekstrak paket tertanam ----------
info "Menyalin persona + skill + config (dari dalam script)..."
EXTRACT_DIR="$(mktemp -d)"
ARCHIVE_LINE=$(grep -an '^__NARA_PAYLOAD_BEGIN__$' "$0" | cut -d: -f1)
tail -n +$((ARCHIVE_LINE + 1)) "$0" | base64 -d > "$EXTRACT_DIR/nara_dist.tar.gz"

tar -xzf "$EXTRACT_DIR/nara_dist.tar.gz" -C "$EXTRACT_DIR"
[ -f "$EXTRACT_DIR/SOUL.md" ]    && cp "$EXTRACT_DIR/SOUL.md"    "$PROFILE_DIR/SOUL.md"
[ -f "$EXTRACT_DIR/config.yaml" ] && cp "$EXTRACT_DIR/config.yaml" "$PROFILE_DIR/config.yaml"
if [ -d "$EXTRACT_DIR/skills" ]; then
  rm -rf "$PROFILE_DIR/skills"
  cp -r "$EXTRACT_DIR/skills" "$PROFILE_DIR/skills"
fi
rm -rf "$EXTRACT_DIR"
ok "Persona + skill + config tersalin."

# ---------- Tulis .env ----------
ENV_FILE="$PROFILE_DIR/.env"
touch "$ENV_FILE"
set_env() {
  local var="$1"; local prompt="$2"
  if [ -n "${!var:-}" ]; then val="${!var}"; else
    read -rsp "  $prompt: " val; echo ""
  fi
  grep -v "^${var}=" "$ENV_FILE" > "$ENV_FILE.tmp" 2>/dev/null || true
  mv "$ENV_FILE.tmp" "$ENV_FILE"
  echo "${var}=${val}" >> "$ENV_FILE"
}
echo ""
info "Menyiapkan kredensial (.env). Kosongkan kalau tidak dipakai."
set_env "NOVITA_API_KEY"       "API key model (Novita)"
set_env "ATMOROUTER_API_KEY"   "API key cadangan (AtmoRouter)"
set_env "ELEVENLABS_API_KEY"   "API key ElevenLabs (suara Nara)"
set_env "TELEGRAM_BOT_TOKEN"   "Token bot Telegram (@BotFather)"
chmod 600 "$ENV_FILE"
ok ".env tersimpan (permission 600)."

# ---------- Set suara ----------
info "Mengatur suara Nara (ElevenLabs)..."
hermes -p "$PROFILE_NAME" config set tts.provider elevenlabs 2>/dev/null || warn "set tts.provider gagal."
hermes -p "$PROFILE_NAME" config set tts.elevenlabs.voice_id "$NARA_VOICE_ID" 2>/dev/null || warn "set voice_id gagal."
ok "Suara Nara: $NARA_VOICE_ID"

# ---------- Atur chat ID pemilik ----------
echo ""
info "Batasi bot ke chat ID pemilik (keamanan)."
read -rp "  Chat ID Telegram kamu (dari @userinfobot): " CHAT_ID
if [ -n "$CHAT_ID" ]; then
  hermes -p "$PROFILE_NAME" config set platforms.telegram.allow_admin_from "[\"$CHAT_ID\"]" 2>/dev/null || warn "allow_admin_from gagal."
  hermes -p "$PROFILE_NAME" config set platforms.telegram.allow_from "[\"$CHAT_ID\"]" 2>/dev/null || warn "allow_from gagal."
  hermes -p "$PROFILE_NAME" config set platforms.telegram.home_channel.chat_id "$CHAT_ID" 2>/dev/null || warn "home_channel.chat_id gagal."
  hermes -p "$PROFILE_NAME" config set platforms.telegram.home_channel.user_id "$CHAT_ID" 2>/dev/null || warn "home_channel.user_id gagal."
  hermes -p "$PROFILE_NAME" config set platforms.telegram.home_channel.name "Nara Owner" 2>/dev/null || warn "home_channel.name gagal."
  ok "Allowlist & home channel diset ke chat ID $CHAT_ID"
else
  warn "Chat ID kosong. Bot menolak semua DM sampai allowlist diisi."
fi

# ---------- Jalankan gateway ----------
info "Memasang layanan gateway..."
loginctl enable-linger "$USER" 2>/dev/null || warn "loginctl tidak tersedia."
hermes -p "$PROFILE_NAME" gateway setup 2>/dev/null || warn "gateway setup perlu manual."
hermes -p "$PROFILE_NAME" gateway restart 2>/dev/null || hermes -p "$PROFILE_NAME" gateway start 2>/dev/null || warn "gagal start gateway."
ok "Gateway dijalankan."

sleep 5
echo ""
info "Status gateway:"
hermes -p "$PROFILE_NAME" gateway status 2>/dev/null || warn "status tidak terbaca."

echo ""
echo -e "${C_B}${C_G}============================================================${C_R}"
echo -e "${C_B}${C_G}  SELESAI — NARA AKTIF${C_R}"
echo -e "${C_B}${C_G}============================================================${C_R}"
echo ""
echo "  • Buka Telegram, chat bot kamu, ketik /new"
echo "  • Log:      hermes -p $PROFILE_NAME logs -f"
echo "  • Restart:  hermes -p $PROFILE_NAME gateway restart"
echo "  • Persona:  edit $PROFILE_DIR/SOUL.md lalu restart"
echo ""
echo "Selamat menikmati Nara Bot kamu! 💕"
exit 0
__NARA_PAYLOAD_BEGIN__

